Xa(a,b){var s=null,r=this.a
return A.b1(a,s,r,s,"\u0645\u0627\u062f\u0629 \u0648\u0627\u062d\u062f\u0629",""+a+" \u0645\u0627\u062f\u0629",s,s)+" \xb7 "+A.b1(b,s,r,s,"\u0645\u0631\u062d\u0644\u0629 \u0648\u0627\u062d\u062f\u0629",""+b+" \u0645\u0631\u062d\u0644\u0629",s,s)+" \u0641\u064a \u062e\u0637 \u0627\u0644\u0625\u0646\u062a\u0627\u062c"},
