XZ(a){return"\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a ("+a+")"},
XM(a){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 ("+a+")"},
Yj(a,b){return a+" "+b},
Xr(a,b){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 "+a+" "+b},
