gCR(){return"\u0644\u06cc\u0633\u062a\u06cc \u0646\u0648\u06ce"},
gOw(){return"\u0646\u0627\u0648\u06cc \u0644\u06cc\u0633\u062a (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gOr(){return"\u062a\u06d5\u0648\u0627\u0648\u0628\u0648\u0648"},
gOu(){return"\u0646\u06cc\u0634\u0627\u0646\u06a9\u0631\u062f\u0646 \u0648\u06d5\u06a9 \u062a\u06d5\u0648\u0627\u0648\u0628\u0648\u0648"},
gOv(){return"\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gOp(){return"\u0626\u06d5\u0645 \u0644\u06cc\u0633\u062a\u06d5 \u0628\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
gOo(){return"\u0626\u06d5\u0645\u06d5 \u0644\u06cc\u0633\u062a\u06d5\u06a9\u06d5 \u0648 \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0648\u06d5\u06cc \u062a\u06ce\u06cc\u062f\u0627\u06cc\u06d5 \u062f\u06d5\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5. \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06ce\u062a\u06d5\u0648\u06d5."},
