gLQ(){return"\u062c\u06c6\u0631\u06ce\u0646 \u067e\u0627\u0634\u06a9\u06c6\u06cc\u0627\u0646"},
gLR(){return"\u062f\u06cc\u0627\u0631 \u062f\u06a9\u06d5\u062a \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u060c \u0648 \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u0647\u0646\u06ce\u0631\u0646\u060c \u062f\u0634\u06ce\u0646 \u0686 \u0628 \u06a9\u06d5\u06cc\u0633\u06cc \u06a4\u06d5 \u06af\u0631\u06ce \u0628\u062f\u06d5\u0646."},
gLC(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u067e\u0627\u0634\u06a9\u06c6\u06cc\u0627\u0646"},
gLD(){return"\u0633\u0648\u06cc\u0686\u0627 \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u2014 \u06a4\u06d5\u0645\u0631\u0627\u06cc \u06af\u0631\u06ce\u062f\u0627\u0646\u0627 \u0647\u06d5\u0631 \u062a\u0634\u062a\u06d5\u06a9\u06cc \u0644 \u0647\u06d5\u0645\u06cc \u062c\u0647\u0627\u0646 \u06a4\u06d5\u062f\u0634\u06ce\u0631\u06cc\u062a\u060c \u0628\u06ce \u06af\u0648\u0647\u062f\u0627\u0646 \u0628 \u0686\u0627\u0631 \u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u062e\u0648\u0627\u0631\u06ce."},
gLK(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u0648\u06ce\u0646\u06d5\u06cc\u0627\u0646"},
gLL(){return"\u0648\u06ce\u0646\u06d5\u06af\u0631\u062a\u0646 \u0648 \u0628\u0627\u0631\u06a9\u0631\u0646\u0627 \u0648\u06ce\u0646\u06d5\u06cc\u0627\u0646."},
gLO(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u06a4\u06cc\u062f\u06cc\u06c6\u06cc\u0627\u0646"},
gLP(){return"\u0628\u06c6 \u0644\u0642\u06d5\u06a9\u06ce \u0646\u0648\u06cc \u0628 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06ce \u0628\u0646\u06d5\u0695\u06d5\u062a \u06a4\u06d5\u0645\u0631\u0627\u06cc\u06d5 \u2014 \u06a4\u06cc\u062f\u06cc\u06c6 \u0628\u06d5\u0631\u06cc \u0628\u0627\u0631\u06a9\u0631\u0646\u06ce \u0646\u0627\u0647\u06ce\u062a\u06d5 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u0646\u060c \u0644\u06d5\u0648\u0645\u0627 \u0645\u06d5\u0632\u0646\u062a\u0631\u06cc\u0646 \u0626\u06d5\u06af\u06d5\u0631\u06d5 \u0628\u06c6 \u062a\u0698\u06cc\u0628\u0648\u0648\u0646\u0627 \u0633\u0646\u0648\u0648\u0631\u06ce \u0628\u06d5\u0644\u0627\u0634 \u06cc\u06ce Supabase."},
