gNs(){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u0627 \u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gNL(){return"\u0634\u06ce\u0648\u0627\u0632\u06ce \u0646\u06d5\u062e\u0634\u06ce \u062f\u062f\u0627\u0646\u0627\u0646"},
gNN(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 \u062f\u062f\u0627\u0646\u0627\u0646 \u0686\u0627\u0648\u0627 \u0644 \u0633\u06d5\u0631 \u0646\u06d5\u062e\u0634\u06d5\u060c \u06a9\u0627\u0631\u062a\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u062e\u0634\u062a\u06d5\u06cc\u0627\u0646 \u062f\u06cc\u0627\u0631 \u062f\u0628\u0646 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u0627 \u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u06ce\u06cc\u06d5\u060c \u0686 \u062a\u0634\u062a \u0628 \u0631\u06d5\u0646\u06af\u06d5\u06a9\u06ce \u062f\u06cc \u0646\u0627\u0647\u06ce\u062a\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646."},
gNK(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 FDI"},
gNM(){return"\u067e\u06cc\u062a\u06ce\u0646 \u0686\u0627\u0631\u06d5\u06a9\u0627\u0646"},
gNI(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: 11\u060c 12\u060c 24\u060c 46"},
gNJ(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: UR1\u060c UR2\u060c UL4\u060c LR6"},
gMz(){return"\u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 \u062f\u0648\u06af\u0645\u06d5\u06cc\u0627 \u0686\u0627\u062a\u0627 \u0647\u0627\u0631\u06cc\u06a9\u0627\u0631\u06cc\u06ce"},
gMA(){return"\u0626\u0627\u06cc\u06a9\u06c6\u0646\u0627 \u0686\u0627\u062a\u06ce \u06cc\u0627 \u0644\u06a4\u06c6\u06a9 \u06cc\u0627 \u0628\u06d5\u0631\u0633\u06a4\u0627 \u067e\u0633\u06cc\u0627\u0631\u06ce\u0646 \u062f\u06d5\u0631\u0628\u0627\u0631\u06d5\u06cc \u0626\u06d5\u067e\u06cc \u062f\u062f\u06d5\u062a. \u0626\u06d5\u06af\u06d5\u0631 \u0631\u06ce\u06af\u0631 \u0628\u06cc\u062a \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0644 \u0633\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a\u060c \u0646\u06d5 \u06cc\u06ce\u0646 \u0647\u06d5\u06a4\u0627\u0644\u06ce\u0646 \u062a\u06d5."},
gMQ(){return"\u0632\u0645\u0627\u0646"},
gMR(){return"\u0626\u06d5\u0648 \u0632\u0645\u0627\u0646\u06ce \u062f \u0647\u06d5\u0645\u06cc \u0626\u06d5\u067e\u06cc \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5."},
ga_U(){return"\u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0686\u0627\u0644\u0627\u06a9"},
ga01(){return"\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06ce\u0646 \u0644 \u0647\u06cc\u06a4\u06cc\u06ce"},
gGh(){return"\u062f\u06d5\u0645 \u0628\u06c6\u0631\u06cc"},
ga02(){return"\u0626\u0627\u0645\u0627\u062f\u06d5 \u0628\u06c6 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06ce"},
