gaaq(){return"\u0686\u0627\u067e\u06a9\u0631\u0646\u0627 \u06a9\u06d5\u0634\u0641\u06ce\u0646 \u0647\u06d5\u0645\u06cc \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646"},
aap(a){return"\u0686\u0627\u067e\u06a9\u0631\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
gaas(){return"\u0686\u0627\u067e\u06a9\u0631\u0646\u0627 \u0633\u06d5\u0631\u062c\u06d5\u0645\u06ce\u0646 \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 (\u0644\u06cc\u0633\u062a\u0627 \u06a9\u0648\u0631\u062a)"},
aar(a){return"\u0686\u0627\u067e\u06a9\u0631\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
gabq(){return"\u0646\u0648\u0648\u06a9\u0631\u0646 \u067e\u06ce\u062f\u06a4\u06cc\u06d5"},
abp(a){return"\u0646\u0648\u0648\u06a9\u0631\u0646\u06d5\u06a9\u0627 \u067e\u06ce\u062f\u06a4\u06cc \u0628\u06d5\u0631\u062f\u06d5\u0633\u062a\u06d5. \u0647\u06cc\u06a4\u06cc\u06d5 \u0626\u06d5\u067e\u06cc \u0628\u06c6 \u0648\u06d5\u0634\u0627\u0646\u0627 "+a+" \u06cc\u0627\u0646 \u0646\u0648\u0648\u062a\u0631 \u0646\u0648\u06cc \u0628\u06a9\u06d5 \u0628\u06c6 \u0628\u06d5\u0631\u062f\u06d5\u0648\u0627\u0645\u0628\u0648\u0648\u0646\u06ce."},
