ga69(){return"\u0686 \u062f\u06a9\u062a\u06c6\u0631 \u062f\u06af\u06d5\u0644 \u0648\u06ce \u0644\u06ce\u06af\u06d5\u0631\u06cc\u0627\u0646\u06ce \u0646\u0627\u06af\u0648\u0646\u062c\u0646."},
a5T(a){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \xab"+a+"\xbb \u0648\u06d5\u06a9 \u062f\u06a9\u062a\u06c6\u0631\u06d5\u06a9\u06ce \u0646\u0648\u06cc"},
gNP(){return"\u0628\u06d5\u062f\u0648\u06cc\u062f\u0627\u0686\u0648\u0648\u0646\u0627 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce\u0646 \u0633\u06a9\u0627\u0646\u06ce"},
gNQ(){return"\u062f\u06d5\u0645\u06ce \u0647\u06d5\u0644\u06a9\u0631\u06cc \u0628\u06cc\u062a\u060c \u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc \u062f\u0647\u06ce\u0644\u06cc\u062a \u062a\u0648 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5\u06cc \u06a9\u06cc\u0698 \u06a9\u06d5\u0633 \u0644 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u0633\u06a9\u0627\u0646\u06d5\u0631 \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06cc \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u06cc\u06d5\u060c \u0648 \u0644 \u0633\u06d5\u0631 \u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u06cc \u0648 \u0644\u06ce\u0628\u0644\u06ce \u06a9\u06d5\u06cc\u0633\u06cc / \u062a\u06a9\u06ce\u062a\u0627 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06ce \u06cc\u0627 \u0686\u0627\u067e\u06a9\u0631\u06cc \u062f\u06cc\u0627\u0631 \u062f\u0628\u06cc\u062a. \u062a\u0646\u06ce \u0628\u06c6 \u0632\u0627\u0646\u06cc\u0646\u06ce\u06cc\u06d5 \u2014 \u0686 \u062a\u0634\u062a \u0698\u06ce \u0646\u0627\u0647\u06ce\u062a\u06d5 \u0647\u0698\u0645\u0627\u0631\u062a\u0646."},
gLG(){return"\u062f\u0627\u0634\u06a9\u0627\u0646\u062f\u0646"},
gLH(){return"\u062f\u06d5\u0645\u06ce \u06a4\u06d5\u0645\u0631\u0627\u06cc \u0628\u06cc\u062a\u060c \u062e\u0627\u0646\u06ce\u0646 \u062f\u0627\u0634\u06a9\u0627\u0646\u062f\u0646\u06ce \u0644 \u0647\u06d5\u0645\u06cc \u062c\u0647\u0627\u0646 \u062f\u0647\u06ce\u0646\u06d5 \u06a4\u06d5\u0634\u0627\u0631\u062a\u0646 \u2014 \u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc\u060c \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u0627 \u06a9\u06d5\u06cc\u0633\u06cc\u060c \u0648 \u067e\u06d5\u0646\u062c\u06d5\u0631\u0627 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646/\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u0627 \u062f\u06a9\u062a\u06c6\u0631\u06cc \u2014 \u0648 \u0686 \u062f\u0627\u0634\u06a9\u0627\u0646\u062f\u0646\u0627 \u0628\u06d5\u0631\u062f\u06d5\u0648\u0627\u0645 \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 \u0646\u0627\u0647\u06ce\u062a\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce\u06a9\u0631\u0646. \u0626\u06d5\u06af\u06d5\u0631 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5 \u0686 \u062c\u0627\u0631\u0627\u0646 \u062f\u0627\u0634\u06a9\u0627\u0646\u062f\u0646\u06ce \u0646\u0627\u06a9\u06d5\u062a \u06a4\u06ce \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5."},
